#include <iostream>
#include <string>
#include <vector>
#include <cstring>
#include <cstdlib>
#include <map>
#include <stdexcept>

using namespace std;

class ArgumentParser {
public:
    string replayDir = ".";
    unsigned int seed = 0;
    int width = 0, height = 0;
    int numPlayers = 0;
    bool noReplay = false;
    bool ignoreTimeouts = false;
    bool override = false;
    bool quiet = false;
    vector<string> botCommands;

    void parse(int argc, char* argv[]) {
        if (argc < 2) {
            throw runtime_error("Please provide the launch command string for at least one bot.\nUse the --help flag for usage details.");
        }

        for (int i = 1; i < argc; i++) {
            string arg = argv[i];

            if (arg == "--help" || arg == "-h") {
                printHelp();
                exit(0);
            } else if (arg == "--version") {
                cout << "\n./executable  version: 1.2\n" << endl;
                exit(0);
            } else if (arg == "-i" || arg == "--replaydirectory") {
                if (i + 1 >= argc) throw runtime_error("Missing argument for -i");
                replayDir = argv[++i];
            } else if (arg == "-s" || arg == "--seed") {
                if (i + 1 >= argc) throw runtime_error("Missing argument for -s");
                seed = stoul(argv[++i]);
            } else if (arg == "-d" || arg == "--dimensions") {
                if (i + 1 >= argc) throw runtime_error("Missing argument for -d");
                string dims = argv[++i];
                sscanf(dims.c_str(), "%d %d", &width, &height);
            } else if (arg == "-n" || arg == "--nplayers") {
                if (i + 1 >= argc) throw runtime_error("Missing argument for -n");
                numPlayers = stoi(argv[++i]);
            } else if (arg == "-r" || arg == "--noreplay") {
                noReplay = true;
            } else if (arg == "-t" || arg == "--timeout") {
                ignoreTimeouts = true;
            } else if (arg == "-o" || arg == "--override") {
                override = true;
            } else if (arg == "-q" || arg == "--quiet") {
                quiet = true;
            } else if (arg == "--" || arg == "--ignore_rest") {
                // All remaining args are bot commands
                for (int j = i + 1; j < argc; j++) {
                    botCommands.push_back(argv[j]);
                }
                break;
            } else if (arg[0] != '-') {
                // This is a bot command
                botCommands.push_back(arg);
            }
        }

        if (botCommands.empty()) {
            throw runtime_error("Please provide the launch command string for at least one bot.\nUse the --help flag for usage details.");
        }
    }

    void printHelp() {
        cout << "\nUSAGE: \n\n   ./executable  [-i <path to directory>] [-s <positive integer>] [-d <a\n"
             << "                 string containing two space-seprated positive integers>]\n"
             << "                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]\n"
             << "                 [-h] <Array of strings> ...\n\n"
             << "Where: \n\n"
             << "   -i <path to directory>,  --replaydirectory <path to directory>\n"
             << "     The path to directory for replay output.\n\n"
             << "   -s <positive integer>,  --seed <positive integer>\n"
             << "     The seed for the map generator.\n\n"
             << "   -d <a string containing two space-seprated positive integers>, \n"
             << "      --dimensions <a string containing two space-seprated positive\n"
             << "      integers>\n"
             << "     The dimensions of the map.\n\n"
             << "   -n <{1,2,3,4,5,6}>,  --nplayers <{1,2,3,4,5,6}>\n"
             << "     Create a map that will accommodate n players [SINGLE PLAYER MODE\n"
             << "     ONLY].\n\n"
             << "   -r,  --noreplay\n"
             << "     Turns off the replay generation.\n\n"
             << "   -t,  --timeout\n"
             << "     Causes game environment to ignore timeouts (give all bots infinite\n"
             << "     time).\n\n"
             << "   -o,  --override\n"
             << "     Overrides player-sent names using cmd args [SERVER ONLY].\n\n"
             << "   -q,  --quiet\n"
             << "     Runs game in quiet mode, producing machine-parsable output.\n\n"
             << "   --,  --ignore_rest\n"
             << "     Ignores the rest of the labeled arguments following this flag.\n\n"
             << "   --version\n"
             << "     Displays version information and exits.\n\n"
             << "   -h,  --help\n"
             << "     Displays usage information and exits.\n\n"
             << "   <Array of strings>  (accepted multiple times)\n"
             << "     Start commands for bots.\n\n\n"
             << "   Halite Game Environment\n";
    }
};

int main(int argc, char* argv[]) {
    try {
        ArgumentParser parser;
        parser.parse(argc, argv);

        // Basic output for now
        for (const auto& cmd : parser.botCommands) {
            cout << cmd << "\n";
        }
        cout << parser.width << " " << parser.height << "\n";

        // Generate a replay filename
        unsigned int timestamp = seed != 0 ? seed : (unsigned)time(nullptr);
        unsigned int random_id = ((unsigned)rand() * 1000) + (unsigned)rand();

        cout << "./" << (unsigned)time(nullptr) << "-" << (seed != 0 ? seed : random_id) << ".hlt " << (seed != 0 ? seed : random_id) << "\n";
        cout << "1 " << parser.botCommands.size() << " 0\n";

        // Print bot count (final line)
        cout << parser.botCommands.size() << " ";

    } catch (const exception& e) {
        cerr << e.what() << endl;
        return 1;
    }

    return 0;
}
