class Map {
public:
    int width, height;
    vector<vector<Cell>> cells;
    mt19937 rng;

    Map(int w, int h, unsigned int seed) : width(w), height(h) {
        rng.seed(seed);
        cells.assign(h, vector<Cell>(w));
        generateMap();
    }

    void generateMap() {
        // Generate production and initial state
        uniform_int_distribution<> prod_dist(1, 20);
        uniform_int_distribution<> owner_dist(0, 1);
        uniform_int_distribution<> strength_dist(0, 255);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                cells[y][x].production = prod_dist(rng);
                cells[y][x].owner = owner_dist(rng);
                cells[y][x].strength = strength_dist(rng);
            }
        }
    }
};

class GameState {
public:
    int width, height;
    int numPlayers;
    vector<Map*> playerMaps;
    vector<vector<vector<Cell>>> frameHistory;

    GameState(int w, int h, int np, unsigned int seed) 
        : width(w), height(h), numPlayers(np) {
        for (int i = 0; i < np; i++) {
            playerMaps.push_back(new Map(w, h, seed + i));
        }
    }

    ~GameState() {
        for (auto m : playerMaps) delete m;
    }
