    int stdin_fd, stdout_fd, stderr_fd;
};

BotProcess launchBot(const string& command) {
    BotProcess bot;

    int stdin_pipe[2], stdout_pipe[2], stderr_pipe[2];

    pipe(stdin_pipe);
    pipe(stdout_pipe);
    pipe(stderr_pipe);

    bot.pid = fork();

    if (bot.pid == 0) {
        // Child process
        dup2(stdin_pipe[0], STDIN_FILENO);
        dup2(stdout_pipe[1], STDOUT_FILENO);
        dup2(stderr_pipe[1], STDERR_FILENO);

        close(stdin_pipe[0]);
        close(stdin_pipe[1]);
        close(stdout_pipe[0]);
        close(stdout_pipe[1]);
        close(stderr_pipe[0]);
        close(stderr_pipe[1]);

        execl("/bin/bash", "bash", "-c", command.c_str(), nullptr);
        exit(127);
    } else {
        // Parent process
        close(stdin_pipe[0]);
        close(stdout_pipe[1]);
        close(stderr_pipe[1]);

        bot.stdin_fd = stdin_pipe[1];
        bot.stdout_fd = stdout_pipe[0];
