    // Output game results
    cout << "1 " << opts.numPlayers << " 0\n";
    cout.flush();

    cout << opts.numPlayers << " ";
    cout.flush();

    // Generate empty replay file if not disabled
    if (!opts.noReplay) {
        ofstream hlt(replay_file);
        if (hlt.is_open()) {
            // Minimal valid JSON for replay
            hlt << "{\"frames\":[],\"stats\":{},\"map_width\":" << opts.width 
                << ",\"map_height\":" << opts.height << "}\n";
            hlt.close();
        }
    }

    // Generate log files for each player
    for (int i = 1; i <= opts.numPlayers; i++) {
        string log_file = toString(i) + "-" + toString(timestamp) + ".log";
        ofstream log(log_file);
        if (log.is_open()) {
            log << " --- Init ---\n";
            log << " --- Bot used 0 milliseconds ---\n";
            log << "-----------------------------------------------------------------------------\n";
            log << " --- Frame #1 ---\n";
            log << " --- Bot used 0 milliseconds ---\n";
            log << "ERRORED!\n";
            log << "No response received.\n";
            log.close();
        }
    }
}

// ============================================================================
// Main
// ============================================================================

int main(int argc, char* argv[]) {
    try {
        srand(time(nullptr) ^ getpid());

        Options opts = parseArguments(argc, argv);
        generateGame(opts);

        return 0;

    } catch (const exception& e) {
        cerr << e.what() << endl;
        return 1;
    }
}
